sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	// Add your code here
	if (source['u_kfz_hersteller']) {
        var companyGR = new GlideRecord('core_company');
        companyGR.addQuery('name', source['u_kfz_hersteller']);
        companyGR.query();

        if (companyGR.next()) {
            target.manufacturer = companyGR.sys_id;
        } else {
            var newCompany = new GlideRecord('core_company');
            newCompany.initialize();
            newCompany.name = source['u_kfz_hersteller'];
            newCompany.active = true;
            newCompany.insert();
            target.manufacturer = newCompany.sys_id;
        }
    }

    // Setze Führerscheinklasse auf "B"
    target.driver_license_class = 'B';

})(source, map, log, target);
